\begin{multline}
\det(M[X\cup \{a,b\}]) = \left( a_{1,1}\det (M[X])+  \sum_{3\leq i,j\leq n}   a_{1,i}a_{j,1}\det (M[X]_{i,j})  \right)
\\  + \left( a_{2,2}\det (M[X])+  \sum_{3\leq i,j\leq n}   a_{2,i}a_{j,2}\det (M[X]_{i,j})  \right)
\\ +  \left( \sum_{3\leq i,j\leq n}   a_{1,i}a_{j,2}\det (M[X]_{i,j})  \right) +\left( \sum_{3\leq i,j\leq n}   a_{2,i}a_{j,1}\det (M[X]_{i,j})  \right). 
\end{multline}
